 72	func newOTLPExporter(ctx context.Context, cfg config.OTLPTracingConfig) (tracesdk.SpanExporter, error) {
 73		endpoint := cfg.Endpoint
 74		if endpoint == "" {
 75			return nil, fmt.Errorf("parsing otlp endpoint: endpoint is empty")
 76		}
 77		// url.Parse treats a bare host:port as a URL scheme. Add the transport
 78		// scheme first so both forms receive the same host validation.
 79		if !strings.Contains(endpoint, "://") {
 80			endpoint = "grpc://" + endpoint
 81		}
 82		u, err := url.Parse(endpoint)
 83		if err != nil {
 84			return nil, fmt.Errorf("parsing otlp endpoint: %w", err)
 85		}
 86		if u.Host == "" || u.User != nil || u.RawQuery != "" || u.Fragment != "" {
 87			return nil, fmt.Errorf("parsing otlp endpoint: invalid endpoint %q", cfg.Endpoint)
 88		}
 89	
 90		var client otlptrace.Client
 91		switch u.Scheme {
 92		case "http", "https":
 93			opts := []otlptracehttp.Option{
 94				otlptracehttp.WithEndpoint(u.Host),
 95				otlptracehttp.WithHeaders(cfg.Headers),
 96			}
 97			if u.Scheme == "http" {
 98				opts = append(opts, otlptracehttp.WithInsecure())
 99			}
100			if u.Path != "" && u.Path != "/" {
101				opts = append(opts, otlptracehttp.WithURLPath(u.Path))
102			}
103			client = otlptracehttp.NewClient(opts...)
104		case "grpc":
105			if u.Path != "" {
106				return nil, fmt.Errorf("parsing otlp endpoint: unexpected path %q", u.Path)
107			}
108			client = otlptracegrpc.NewClient(
109				otlptracegrpc.WithEndpoint(u.Host),
110				otlptracegrpc.WithHeaders(cfg.Headers),
111				otlptracegrpc.WithInsecure(),
112			)
113		default:
114			return nil, fmt.Errorf("parsing otlp endpoint: unsupported scheme %q", u.Scheme)
115		}
116		return otlptrace.New(ctx, client)
117	}
